import {createPuzzle,reducePuzzle,validateCompletion} from './puzzles.js';
export const chapters=[
{title:'The forgotten invitation',person:'Nujhat',fullName:'Nujhat Hossain',need:'Find the invitation. Make room for someone.',intro:'Everyone is gathering at Fezziwig’s table. Yet one chair remains empty. Perhaps the past has something left to tell us.',line:'I thought the celebration was for everyone else. There was no invitation for me.',reply:'Let me look around. There may still be time.',deed:'Invite someone who might otherwise be left out.',required:['invitation'],items:[{id:'invitation',name:'Sealed invitation',kind:'letter',x:27,y:62},{id:'bell',name:'Silver bell',kind:'bell',x:74,y:51},{id:'holly',name:'Holly sprig',kind:'holly',x:48,y:30}],use:'invitation',core:'invite',find:'uncover',success:'Nujhat takes her place at the table. A missed invitation becomes a memory of belonging.',hint:'Rewind the clock. Search the writing desk for a sealed envelope. Select it in your satchel, then speak to Nujhat.'},
{title:'Words worth saving',person:'Hafsa',fullName:'Hafsa Ibrahim',need:'Close the draft. Rescue a lost thank-you.',intro:'A cold draft steals across the desk. A letter that could have warmed a heart is about to disappear into the snow.',line:'There was a letter here, just a moment ago. I never got to read what it said.',reply:'A few kind words deserve to be kept. I will find it.',deed:'Send a sincere thank-you to someone who helped you.',required:['letter'],items:[{id:'letter',name:'Thank-you letter',kind:'letter',x:20,y:40},{id:'quill',name:'Ivory quill',kind:'quill',x:39,y:58},{id:'star',name:'Gilded star',kind:'star',x:62,y:20}],use:'letter',core:'deliver',find:'recover',success:'Hafsa reads the rescued letter. Words that nearly vanished bring warmth back to the room.',hint:'Rewind, then close the blue window. Find the letter on its ledge. Select the letter and return it to Hafsa.'},
{title:'The little wooden reindeer',person:'Foysal',fullName:'Foysal Hasan Shakil',need:'Repair the route. Bring a keepsake home.',intro:'A wooden toy rattles toward a broken track. Scrooge remembers the weight of small things made with love.',line:'I made that reindeer by hand. The old cart track is broken. Can you help it reach the end safely?',reply:'We can give this memory a gentler ending.',deed:'Take care of something that matters to someone else.',required:['handle','ribbon'],items:[{id:'handle',name:'Brass switch handle',kind:'handle',x:52,y:56},{id:'ribbon',name:'Velvet ribbon',kind:'ribbon',x:76,y:85},{id:'button',name:'Pearl button',kind:'button',x:34,y:73}],success:'The cart takes the safe track. Foysal’s little reindeer survives to bring someone joy.',hint:'Rewind. Find a brass handle by the shelves and a ribbon near the presents. Use the handle on the track switch, then the ribbon on the toy cart. Continue the memory.'}
];
export function initial(){return {level:0,done:[],core:createPuzzle(0),bag:[],found:[],selected:null,talked:false,committed:false};}
export function act(old,event){const s={...old,done:[...old.done],bag:[...old.bag],found:[...old.found]};const q=chapters[s.level];
if(event.type==='talk'){s.talked=true;return s;}
if(event.type==='select'){if(!s.bag.includes(event.id))throw Error('That item is not in your satchel.');s.selected=s.selected===event.id?null:event.id;return s;}
if(event.type==='time'){s.core=reducePuzzle(s.core,{type:event.action});return s;}
if(event.type==='find'){
 const item=q.items.find(i=>i.id===event.id);if(!item)throw Error('Look a little more closely.');if(s.found.includes(item.id))return s;
 if(q.required.includes(item.id)){if(!s.core.rewound||s.core.time!==0)throw Error('This moment has already passed. Rewind the clock to search before it was lost.');if(!s.talked)throw Error('Speak with '+q.person+' first to understand what is missing.');if(q.find)s.core=reducePuzzle(s.core,{type:q.find});}
 s.found.push(item.id);s.bag.push(item.id);return s;
}
if(event.type==='window'){if(s.level!==1)throw Error('The window holds another story.');s.core=reducePuzzle(s.core,{type:'window'});return s;}
if(event.type==='use'){
 let expected,core;if(event.target==='person'&&s.level<2){expected=q.use;core=q.core;}else if(event.target==='switch'&&s.level===2){expected='handle';core='switch';}else if(event.target==='cart'&&s.level===2){expected='ribbon';core='secure';}else throw Error('That is not where this item belongs.');
 if(s.selected!==expected||!s.bag.includes(expected))throw Error('Select the right item in your satchel first.');if(!s.talked)throw Error('Speak with '+q.person+' before changing the memory.');s.core=reducePuzzle(s.core,{type:core});s.bag=s.bag.filter(x=>x!==expected);s.selected=null;return s;
}
if(event.type==='collect'){if(event.commit!==true||!s.core.solved)throw Error('Watch the changed outcome and make your kindness promise first.');validateCompletion(s.level,s.core.history);if(!s.done.includes(s.level))s.done.push(s.level);s.committed=true;return s;}
if(event.type==='next'){if(!s.done.includes(s.level))throw Error('Restore this memory first.');if(s.level===2)throw Error('Christmas Past is complete.');s.level++;s.core=createPuzzle(s.level);s.bag=[];s.found=[];s.selected=null;s.talked=false;s.committed=false;return s;}
if(event.type==='reset'){s.core=createPuzzle(s.level);s.bag=[];s.found=[];s.selected=null;s.talked=false;return s;}
throw Error('Unknown interaction.');}
